(function (global) {
	'use strict';

	function isArray(value) {
		return Array.isArray(value);
	}

	function clamp(value, min, max) {
		return Math.max(min, Math.min(max, value));
	}

	function getContext(input) {
		if (!input) {
			return null;
		}
		if (input.canvas) {
			return input;
		}
		if (typeof input.getContext === 'function') {
			return input.getContext('2d');
		}
		return null;
	}

	function getCanvas(ctx) {
		if (!ctx) {
			return null;
		}
		return ctx.canvas || ctx;
	}

	function getColors(dataset, index) {
		if (isArray(dataset.backgroundColor)) {
			return dataset.backgroundColor[index % dataset.backgroundColor.length];
		}
		return dataset.backgroundColor || dataset.borderColor || '#2d5bff';
	}

	function getBorder(dataset) {
		return dataset.borderColor || dataset.backgroundColor || '#2d5bff';
	}

	function clear(ctx) {
		var canvas = getCanvas(ctx);
		if (!canvas) {
			return;
		}
		ctx.clearRect(0, 0, canvas.width, canvas.height);
	}

	function resizeCanvas(ctx) {
		var canvas = getCanvas(ctx);
		if (!canvas) {
			return { width: 0, height: 0, ratio: 1 };
		}

		var ratio = Math.max(1, window.devicePixelRatio || 1);
		var width = Math.max(320, canvas.clientWidth || canvas.parentNode && canvas.parentNode.clientWidth || canvas.width || 320);
		var height = Math.max(220, canvas.clientHeight || canvas.parentNode && canvas.parentNode.clientHeight || canvas.height || 220);

		canvas.width = Math.round(width * ratio);
		canvas.height = Math.round(height * ratio);
		canvas.style.width = width + 'px';
		canvas.style.height = height + 'px';

		if (ctx && typeof ctx.setTransform === 'function') {
			ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
		}

		return { width: width, height: height, ratio: ratio };
	}

	function drawText(ctx, text, x, y, options) {
		options = options || {};
		ctx.save();
		ctx.font = options.font || '12px sans-serif';
		ctx.fillStyle = options.fillStyle || '#334155';
		ctx.textAlign = options.align || 'left';
		ctx.textBaseline = options.baseline || 'alphabetic';
		ctx.direction = 'rtl';
		ctx.fillText(text, x, y);
		ctx.restore();
	}

	function drawGrid(ctx, box, maxValue, steps) {
		var stepValue = maxValue / steps;
		ctx.save();
		ctx.strokeStyle = 'rgba(148, 163, 184, 0.18)';
		ctx.lineWidth = 1;
		for (var i = 0; i <= steps; i++) {
			var y = box.top + box.height - (box.height * i / steps);
			ctx.beginPath();
			ctx.moveTo(box.left, y);
			ctx.lineTo(box.left + box.width, y);
			ctx.stroke();
			drawText(ctx, Math.round(stepValue * i), box.left - 10, y + 4, {
				font: '11px sans-serif',
				fillStyle: '#64748b',
				align: 'right'
			});
		}
		ctx.restore();
	}

	function drawAxes(ctx, box) {
		ctx.save();
		ctx.strokeStyle = 'rgba(148, 163, 184, 0.35)';
		ctx.lineWidth = 1;
		ctx.beginPath();
		ctx.moveTo(box.left, box.top);
		ctx.lineTo(box.left, box.top + box.height);
		ctx.lineTo(box.left + box.width, box.top + box.height);
		ctx.stroke();
		ctx.restore();
	}

	function drawLineChart(ctx, data, size) {
		var labels = isArray(data.labels) ? data.labels : [];
		var datasets = isArray(data.datasets) ? data.datasets : [];
		var canvas = getCanvas(ctx);
		var width = size.width;
		var height = size.height;
		var box = {
			left: 48,
			right: 20,
			top: 20,
			bottom: 44
		};
		box.width = Math.max(10, width - box.left - box.right);
		box.height = Math.max(10, height - box.top - box.bottom);

		var maxValue = 0;
		datasets.forEach(function (dataset) {
			(dataset.data || []).forEach(function (value) {
				maxValue = Math.max(maxValue, Number(value) || 0);
			});
		});
		maxValue = maxValue <= 0 ? 1 : maxValue;
		var steps = 5;

		drawGrid(ctx, box, maxValue, steps);
		drawAxes(ctx, box);

		datasets.forEach(function (dataset) {
			var values = isArray(dataset.data) ? dataset.data : [];
			if (!values.length) {
				return;
			}

			ctx.save();
			ctx.strokeStyle = getBorder(dataset);
			ctx.lineWidth = 2.5;
			ctx.fillStyle = dataset.backgroundColor || 'rgba(45, 91, 255, 0.12)';
			ctx.beginPath();

			var stepX = labels.length > 1 ? box.width / (labels.length - 1) : box.width;
			values.forEach(function (value, index) {
				var numeric = Number(value) || 0;
				var x = box.left + (stepX * index);
				var y = box.top + box.height - (box.height * numeric / maxValue);
				if (0 === index) {
					ctx.moveTo(x, y);
				} else {
					ctx.lineTo(x, y);
				}
			});
			ctx.stroke();

			if (dataset.fill) {
				var firstX = box.left;
				var lastX = box.left + box.width;
				var lastY = box.top + box.height - (box.height * (Number(values[values.length - 1]) || 0) / maxValue);
				ctx.lineTo(lastX, box.top + box.height);
				ctx.lineTo(firstX, box.top + box.height);
				ctx.closePath();
				ctx.globalAlpha = 0.7;
				ctx.fill();
			}

			ctx.globalAlpha = 1;
			values.forEach(function (value, index) {
				var numeric = Number(value) || 0;
				var x = box.left + (stepX * index);
				var y = box.top + box.height - (box.height * numeric / maxValue);
				ctx.beginPath();
				ctx.fillStyle = getBorder(dataset);
				ctx.arc(x, y, 3.5, 0, Math.PI * 2);
				ctx.fill();
			});
			ctx.restore();
		});

		if (labels.length) {
			var stepXLabel = labels.length > 1 ? box.width / (labels.length - 1) : box.width;
			labels.forEach(function (label, index) {
				var x = box.left + (stepXLabel * index);
				drawText(ctx, label, x, height - 18, {
					font: '11px sans-serif',
					fillStyle: '#64748b',
					align: 'center'
				});
			});
		}
	}

	function drawBarChart(ctx, data, size) {
		var labels = isArray(data.labels) ? data.labels : [];
		var datasets = isArray(data.datasets) ? data.datasets : [];
		var width = size.width;
		var height = size.height;
		var box = {
			left: 48,
			right: 20,
			top: 18,
			bottom: 44
		};
		box.width = Math.max(10, width - box.left - box.right);
		box.height = Math.max(10, height - box.top - box.bottom);

		var maxValue = 0;
		datasets.forEach(function (dataset) {
			(dataset.data || []).forEach(function (value) {
				maxValue = Math.max(maxValue, Number(value) || 0);
			});
		});
		maxValue = maxValue <= 0 ? 1 : maxValue;
		var steps = 5;

		drawGrid(ctx, box, maxValue, steps);
		drawAxes(ctx, box);

		var datasetCount = Math.max(1, datasets.length);
		var groupWidth = labels.length ? box.width / labels.length : box.width;
		var innerWidth = groupWidth * 0.72;
		var barWidth = innerWidth / datasetCount;

		labels.forEach(function (label, labelIndex) {
			var groupX = box.left + (groupWidth * labelIndex) + ((groupWidth - innerWidth) / 2);
			datasets.forEach(function (dataset, datasetIndex) {
				var values = isArray(dataset.data) ? dataset.data : [];
				var numeric = Number(values[labelIndex]) || 0;
				var barHeight = box.height * numeric / maxValue;
				var x = groupX + (barWidth * datasetIndex);
				var y = box.top + box.height - barHeight;
				ctx.save();
				ctx.fillStyle = getColors(dataset, labelIndex);
				ctx.fillRect(x, y, Math.max(1, barWidth - 4), barHeight);
				ctx.restore();
			});
			drawText(ctx, label, box.left + (groupWidth * labelIndex) + (groupWidth / 2), height - 18, {
				font: '11px sans-serif',
				fillStyle: '#64748b',
				align: 'center'
			});
		});
	}

	function drawDoughnutChart(ctx, data, size) {
		var labels = isArray(data.labels) ? data.labels : [];
		var datasets = isArray(data.datasets) ? data.datasets : [];
		var values = datasets.length && isArray(datasets[0].data) ? datasets[0].data : [];
		var colors = datasets.length ? datasets[0].backgroundColor : [];
		var total = values.reduce(function (sum, value) {
			return sum + (Number(value) || 0);
		}, 0);
		var width = size.width;
		var height = size.height;
		var cx = width / 2;
		var cy = height / 2;
		var radius = Math.min(width, height) * 0.32;
		var innerRadius = radius * 0.62;
		var startAngle = -Math.PI / 2;

		if (total <= 0) {
			drawText(ctx, 'داده‌ای برای نمایش وجود ندارد', cx, cy, {
				font: '14px sans-serif',
				fillStyle: '#64748b',
				align: 'center',
				baseline: 'middle'
			});
			return;
		}

		values.forEach(function (value, index) {
			var numeric = Number(value) || 0;
			var angle = (numeric / total) * Math.PI * 2;
			ctx.beginPath();
			ctx.moveTo(cx, cy);
			ctx.fillStyle = isArray(colors) ? colors[index % colors.length] : (colors || '#2d5bff');
			ctx.arc(cx, cy, radius, startAngle, startAngle + angle, false);
			ctx.closePath();
			ctx.fill();
			startAngle += angle;
		});

		ctx.save();
		ctx.globalCompositeOperation = 'destination-out';
		ctx.beginPath();
		ctx.arc(cx, cy, innerRadius, 0, Math.PI * 2);
		ctx.fill();
		ctx.restore();

		drawText(ctx, String(total), cx, cy + 3, {
			font: '600 22px sans-serif',
			fillStyle: '#0f172a',
			align: 'center',
			baseline: 'middle'
		});
		drawText(ctx, 'مجموع', cx, cy + 24, {
			font: '12px sans-serif',
			fillStyle: '#64748b',
			align: 'center',
			baseline: 'middle'
		});
	}

	function Chart(context, config) {
		if (!(this instanceof Chart)) {
			return new Chart(context, config);
		}

		this.ctx = getContext(context);
		this.config = config || {};
		this.type = this.config.type || 'bar';
		this.canvas = getCanvas(this.ctx);
		this.render();
	}

	Chart.prototype.render = function () {
		if (!this.ctx || !this.canvas) {
			return;
		}

		var size = resizeCanvas(this.ctx);
		clear(this.ctx);

		var data = this.config.data || {};
		switch (this.type) {
			case 'line':
				drawLineChart(this.ctx, data, size);
				break;
			case 'doughnut':
				drawDoughnutChart(this.ctx, data, size);
				break;
			case 'bar':
			default:
				drawBarChart(this.ctx, data, size);
				break;
		}
	};

	Chart.prototype.destroy = function () {
		if (this.ctx) {
			clear(this.ctx);
		}
	};

	global.Chart = Chart;
}(window));
